window.docContents[125].resolve({"/rules/PL1007/#PL1007-limitations":{"contents":"Term-parameterized and partial-application registrations are unsupported shapes, not proofs of incorrectness; restate them as closed full-domain contracts.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1007: Executable contracts require supported closed evidence","header":"Limitations and unsupported cases","id":"/rules/PL1007/#PL1007-limitations"},"/rules/PL4004/#PL4004-limitations":{"contents":"Teaching fences are re-elaborated for authentication, so their imports are paid twice; keep them small.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4004: Teaching examples require authenticated compiler classification","header":"Limitations and unsupported cases","id":"/rules/PL4004/#PL4004-limitations"},"/rules/PL5003/#PL5003-limitations":{"contents":"Setext headings and closing sequences such as # Intent # are not recognized as Intent headings.\n\nThe editor reports this rule only when the module has finished elaborating without errors; a module with elaboration errors gets PL2005 (incomplete) instead.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5003: Registered public material declarations require an Intent section","header":"Limitations and unsupported cases","id":"/rules/PL5003/#PL5003-limitations"}});